import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BjkiRu3Q.js";const h=JSON.parse('{"title":"AADE/myDATA & EDXEIX sandbox operations","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/regulatory-sandbox.md","filePath":"integrations/regulatory-sandbox.md"}'),i={name:"integrations/regulatory-sandbox.md"};function n(s,e,c,d,l,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="aade-mydata-edxeix-sandbox-operations" tabindex="-1">AADE/myDATA &amp; EDXEIX sandbox operations <a class="header-anchor" href="#aade-mydata-edxeix-sandbox-operations" aria-label="Permalink to &quot;AADE/myDATA &amp; EDXEIX sandbox operations&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed against TransferBook+ v0.7.26. Verify the installed release, company, permissions and configuration. Use authorized synthetic data for training. Commercial activation is not asserted.</p></div><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Persistent regulatory records and attempt history are implemented for sandbox preparation. Live regulatory submission is explicitly blocked in the inspected source. Neither a sandbox record nor a generated reference is an official submission, statutory document or compliance certification.</p><h2 id="authorized-sandbox-workflow" tabindex="-1">Authorized sandbox workflow <a class="header-anchor" href="#authorized-sandbox-workflow" aria-label="Permalink to &quot;Authorized sandbox workflow&quot;">​</a></h2><ol><li>Confirm the company, invoice or reservation, user permission and synthetic test environment.</li><li>For AADE/myDATA, prepare a sandbox record from an eligible invoice with the required invoice-write permission. Review the stored document and attempt history with the responsible accounting administrator.</li><li>For EDXEIX, use the authorized dispatch workflow to issue a sandbox record for the correct reservation and leg, and review supported extension/cancellation operations. Chauffeur access is restricted; do not use another chauffeur&#39;s assignment or company.</li><li>Verify the stored record and audit status. Do not represent a sandbox result as an official reference, permission to operate or tax submission.</li><li>If a live attempt is blocked, retain the recorded result and follow the approved manual statutory process. Do not bypass the block.</li></ol><p>Before future live activation, confirm current official specifications, credentials, account ownership, required legal/accounting review, permissions, actual acceptance and operating procedure. No live credential recipe is approved for this release.</p><p>See <a href="/integrations/third-party-api-setup.html">Third-party API setup</a> and <a href="/security-privacy/">Security &amp; Privacy</a>.</p>',8)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
